<style>
main{min-width:0}.sc-intro{margin:6px 0 0;font-size:12px;color:#718087;line-height:1.7}.sc-actions{display:flex;gap:8px;flex-wrap:wrap}.sc-button{display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;border:1px solid #ccd8e5;border-radius:7px;background:#fff;color:#334155;font:inherit;font-size:12px;font-weight:700;text-decoration:none;cursor:pointer;white-space:nowrap}.sc-button.primary{background:#1769d1;border-color:#1769d1;color:#fff}.sc-page{display:grid;gap:16px;min-width:0}.sc-tabs{display:flex;gap:8px;border-bottom:1px solid #dfe6ee;padding-bottom:12px}.sc-tabs a{padding:9px 14px;color:#526473;font-size:12px;font-weight:700;text-decoration:none;border-radius:6px}.sc-tabs a.active{background:#1769d1;color:#fff}.sc-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px}.sc-card,.sc-kpi{background:#fff;border:1px solid #e2e8ee;border-radius:10px;padding:20px;min-width:0}.sc-kpi{padding:16px 18px}.sc-kpi span{display:block;font-size:11px;color:#718087}.sc-kpi strong{display:block;font-size:22px;color:#16242b;margin-top:7px;font-variant-numeric:tabular-nums}.sc-card h2{font-size:16px;margin:0 0 7px}.sc-filters{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin:18px 0}.sc-field{display:grid;gap:6px;min-width:0;color:#526473;font-size:11px;font-weight:700}.sc-filters .sc-field{flex:1 1 150px}.sc-field input,.sc-field select,.sc-field textarea{width:100%;min-width:0;padding:10px 11px;border:1px solid #cdd8e3;border-radius:7px;background:#fff;color:#334155;font:inherit;font-size:13px;font-weight:500}.sc-field textarea{resize:vertical}.sc-page :is(input,select,textarea,button,a):focus-visible{outline:2px solid #a7c9f4;outline-offset:2px}.sc-scroll{overflow-x:auto}.sc-table{width:100%;min-width:650px;border-collapse:collapse;font-size:12px}.sc-table th{padding:11px 12px;background:#f7f9fb;text-align:left;font-size:10px;color:#718087;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}.sc-table td{padding:14px 12px;border-bottom:1px solid #edf0f4;vertical-align:middle}.sc-table .number{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}.sc-table a{color:#1057b0;text-decoration:none;font-weight:700}.sc-table small{display:block;font-size:10px;color:#718087;margin-top:4px;overflow-wrap:anywhere}.sc-badge{display:inline-block;padding:4px 8px;border-radius:5px;font-size:10px;font-weight:700;white-space:nowrap;background:#edf8ef;color:#166534}.sc-badge.low{background:#fff5df;color:#956116}.sc-badge.out{background:#fff0ee;color:#b42318}.sc-muted{color:#718087;font-size:11px;line-height:1.6}.sc-empty{text-align:center!important;padding:30px!important;color:#718087}.sc-message{padding:12px 16px;border:1px solid #c7e7ce;border-radius:8px;color:#166534;background:#edf8ef;font-size:12px;line-height:1.7}.sc-message.error{background:#fff0ee;color:#b42318;border-color:#f1ccc6}.sc-adjust-grid{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:16px;align-items:start;max-width:1100px}.sc-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:20px}.sc-wide{grid-column:1/-1}.sc-preview{position:sticky;top:16px;display:grid;gap:18px}.sc-preview strong{font-size:26px;display:block;color:#16242b;margin-top:7px}.sc-preview .sc-muted{display:block}.sc-preview p{margin:0}.sc-footer{display:flex;gap:8px;justify-content:flex-end;margin-top:20px}.sc-card [hidden]{display:none!important}@media(max-width:1050px){.sc-adjust-grid{grid-template-columns:minmax(0,1fr)}.sc-preview{position:static}.header-row{flex-wrap:wrap;gap:14px}}@media(max-width:600px){.sc-form-grid{grid-template-columns:minmax(0,1fr)}.sc-card{padding:15px}.sc-field input,.sc-field select,.sc-field textarea{font-size:16px}.sc-kpi strong{font-size:19px}.sc-actions{width:100%}}
</style>
